import Link from "next/link";
import { ReactNode } from "react";

type ButtonProps = {
  href?: string;
  children: ReactNode;
  variant?: "primary" | "secondary" | "ghost";
  size?: "md" | "lg";
  className?: string;
  onClick?: () => void;
  type?: "button" | "submit";
};

const base =
  "inline-flex items-center justify-center gap-2 rounded-full font-medium transition-all duration-300 whitespace-nowrap focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/60";

const variants: Record<string, string> = {
  primary:
    "bg-gradient-to-r from-[#7c5cff] to-[#22d3ee] text-white shadow-[0_0_0_1px_rgba(255,255,255,0.08)_inset,0_10px_30px_-10px_rgba(124,92,255,0.6)] hover:shadow-[0_0_0_1px_rgba(255,255,255,0.12)_inset,0_16px_40px_-10px_rgba(124,92,255,0.8)] hover:-translate-y-0.5",
  secondary:
    "bg-white/5 text-foreground border border-white/15 hover:bg-white/10 hover:-translate-y-0.5",
  ghost: "text-muted hover:text-foreground",
};

const sizes: Record<string, string> = {
  md: "px-5 py-2.5 text-sm",
  lg: "px-7 py-3.5 text-base",
};

export default function Button({
  href,
  children,
  variant = "primary",
  size = "md",
  className = "",
  onClick,
  type = "button",
}: ButtonProps) {
  const classes = `${base} ${variants[variant]} ${sizes[size]} ${className}`;

  if (href) {
    return (
      <Link href={href} className={classes}>
        {children}
      </Link>
    );
  }

  return (
    <button type={type} onClick={onClick} className={classes}>
      {children}
    </button>
  );
}
